{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        pid = n.get('parent')
        if pid is not None:
            children[pid].append(n['id'])
    retained = set(node_map.keys())
    removed = []
    roots = [n['id'] for n in nodes if n['parent'] is None]
    root_id = roots[0] if roots else None
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if not n['removable']:
            continue
        if nid == root_id:
            continue
        if n['symbol'] in required_symbols:
            continue
        if any(cid in retained for cid in children[nid]):
            continue
        retained.remove(nid)
        removed.append(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"
}
